fun placeOrder(...): Order {
    val order = tx.execute { savePendingOrderAndHold(accountId, command) }   // 커밋
    if (order.mode.isKis()) {
        val result = runCatching { kis.placeOrder(order) }    // 트랜잭션 밖
        tx.execute { applyKisResult(order.id!!, result) }     // 새 트랜잭션
    }
    return order
}

